// Package python_renderer renders the contract as Python source: the enums, the event types, the error codes and the
// envelope dataclasses, in the package telemetry.internal.domain.value_objects. The output has 4-space indents,
// double quotes, lines of at most 120 characters and LF line ends, and imports only the standard library.
package python_renderer

import (
	"fmt"
	"sort"
	"strconv"
	"strings"

	"github.com/DanielCalvo-Calvicia/telemetry/tools/contract_generator/internal/domain"
)

// value_objects_package is the Python package of the generated files, used to import one generated module from
// another (the Python rules of the repository do not allow relative imports).
const value_objects_package = "telemetry.internal.domain.value_objects"

// generated_marker is the first line of every file.
const generated_marker = "# Code generated by contract_generator; DO NOT EDIT."

// line_limit is the longest line of the output.
const line_limit = 120

// Renderer renders the Python files.
type Renderer struct{}

// NewRenderer returns the Python renderer.
func NewRenderer() Renderer {
	return Renderer{}
}

// Render returns the four generated files. The contract must be sorted.
func (Renderer) Render(contract domain.Contract) ([]domain.GeneratedFile, error) {
	return []domain.GeneratedFile{
		{Name: "enums_generated.py", Content: []byte(render_enums(contract))},
		{Name: "event_types_generated.py", Content: []byte(render_event_types(contract))},
		{Name: "error_codes_generated.py", Content: []byte(render_error_codes(contract))},
		{Name: "envelope_generated.py", Content: []byte(render_structs(contract))},
	}, nil
}

// module assembles a file: the header, the docstring, the import block (empty or ending in a line end) and the blocks
// of code (each ending in a line end), with the blank lines of PEP 8: two before every top-level definition that
// follows an import or another block, and one between the docstring and the first line of code.
func module(sources []string, docstring string, imports string, blocks []string) string {
	var text strings.Builder
	text.WriteString(generated_marker + "\n")
	for _, source := range sources {
		text.WriteString("# Source: " + source + "\n")
	}
	text.WriteString("\n\"\"\"" + docstring + "\"\"\"\n")
	if imports != "" {
		text.WriteString("\n" + imports)
	}
	for position, block := range blocks {
		separator := "\n\n"
		if position == 0 && imports == "" {
			separator = "\n"
		}
		text.WriteString(separator + block)
	}
	return text.String()
}

func render_enums(contract domain.Contract) string {
	var sources []string
	var blocks []string
	for _, enum := range contract.Enums {
		sources = append(sources, enum.Source)
		var block strings.Builder
		fmt.Fprintf(&block, "class %s(str, enum.Enum):\n    \"\"\"The enum of %s.\"\"\"\n\n", domain.PascalCase(enum.Name), enum.Source)
		for _, value := range enum.Values {
			fmt.Fprintf(&block, "    %s = %s\n", domain.UpperSnake(value), strconv.Quote(value))
		}
		blocks = append(blocks, block.String())
	}
	imports := ""
	if len(blocks) > 0 {
		imports = "import enum\n"
	}
	return module(sources, "The enums of the contract (contracts/enums).", imports, blocks)
}

func render_event_types(contract domain.Contract) string {
	var constants strings.Builder
	tuple := "EVENT_TYPES: tuple[str, ...] = ()\n"
	if len(contract.EventTypes) > 0 {
		tuple = "EVENT_TYPES: tuple[str, ...] = (\n"
	}
	for _, event_type := range contract.EventTypes {
		member := "EVENT_TYPE_" + domain.UpperSnake(event_type.Name)
		fmt.Fprintf(&constants, "%s = %s\n", member, strconv.Quote(event_type.Name))
		tuple += "    " + member + ",\n"
	}
	if len(contract.EventTypes) > 0 {
		tuple += ")\n"
	}
	block := tuple
	if len(contract.EventTypes) > 0 {
		block = constants.String() + "\n" + tuple
	}
	return module([]string{domain.SourcePrefix + domain.RegistryPath}, "The event types of the registry (contracts/events/registry.yaml).", "", []string{block})
}

func render_error_codes(contract domain.Contract) string {
	var constants strings.Builder
	table := "ERROR_CODES: dict[str, ErrorCodeInfo] = {}\n"
	if len(contract.ErrorCodes) > 0 {
		table = "ERROR_CODES: dict[str, ErrorCodeInfo] = {\n"
	}
	for _, error_code := range contract.ErrorCodes {
		member := "ERROR_CODE_" + domain.UpperSnake(error_code.Code)
		fmt.Fprintf(&constants, "%s = %s\n", member, strconv.Quote(error_code.Code))
		table += fmt.Sprintf("    %s: ErrorCodeInfo(\n        code=%s,\n", member, member)
		table += fmt.Sprintf("        category=FailureCategory.%s,\n", domain.UpperSnake(error_code.Category))
		table += wrap_literal("        ", "default_message=", error_code.DefaultMessage, ",") + "    ),\n"
	}
	if len(contract.ErrorCodes) > 0 {
		table += "}\n"
	}
	imports := "import dataclasses\n\nfrom " + value_objects_package + ".enums_generated import FailureCategory\n"
	info := "@dataclasses.dataclass(frozen=True)\nclass ErrorCodeInfo:\n    \"\"\"An error code of the catalog.\"\"\"\n\n" +
		"    code: str\n    category: FailureCategory\n    default_message: str\n"
	codes := table
	if len(contract.ErrorCodes) > 0 {
		codes = constants.String() + "\n" + table
	}
	return module([]string{domain.SourcePrefix + domain.CatalogPath}, "The error codes of the catalog (contracts/errors/catalog.yaml).", imports, []string{info, codes})
}

func render_structs(contract domain.Contract) string {
	var sources []string
	var blocks []string
	enums := map[string]bool{}
	uses_attributes := false
	for _, declared := range contract.Structs {
		sources = append(sources, declared.Source)
		var block strings.Builder
		fmt.Fprintf(&block, "@dataclasses.dataclass\nclass %s:\n    \"\"\"Mirror of %s.\"\"\"\n\n", domain.PascalCase(declared.Name), declared.Source)
		for _, field := range declared.OrderedFields() {
			uses_attributes = uses_attributes || field.Kind == domain.KindAttributes
			if field.Kind == domain.KindEnum {
				enums[domain.PascalCase(field.Ref)] = true
			}
			if field.Required {
				fmt.Fprintf(&block, "    %s: %s\n", field.JSONName, python_type(field))
			} else {
				fmt.Fprintf(&block, "    %s: %s | None = None\n", field.JSONName, python_type(field))
			}
		}
		blocks = append(blocks, block.String())
	}
	if uses_attributes {
		blocks = append([]string{"Attributes = dict[str, Any]\n"}, blocks...)
	}
	return module(sources, "The envelope and its objects, generated from the schemas of contracts/schemas.", struct_imports(enums, len(blocks) > 0), blocks)
}

// struct_imports returns the import block of the struct file: the future import, the standard library and the enums
// the structs use. A file without a struct imports nothing.
func struct_imports(enums map[string]bool, has_structs bool) string {
	if !has_structs {
		return ""
	}
	imports := "from __future__ import annotations\n\nimport dataclasses\nfrom typing import Any\n"
	if len(enums) > 0 {
		names := make([]string, 0, len(enums))
		for name := range enums {
			names = append(names, name)
		}
		sort.Strings(names)
		imports += "\nfrom " + value_objects_package + ".enums_generated import " + strings.Join(names, ", ") + "\n"
	}
	return imports
}

// python_type returns the annotation of a field, without the optional part.
func python_type(field domain.Field) string {
	switch field.Kind {
	case domain.KindString:
		return "str"
	case domain.KindNumber:
		return "float"
	case domain.KindInteger:
		return "int"
	case domain.KindBoolean:
		return "bool"
	case domain.KindEnum, domain.KindStruct:
		return domain.PascalCase(field.Ref)
	case domain.KindAttributes:
		return "Attributes"
	default:
		return "dict[str, Any]"
	}
}

// wrap_literal returns the line of a keyword argument whose value is a string. If the line is longer than the limit
// it splits the text in adjacent literals inside parentheses, so no line is too long.
func wrap_literal(indent string, prefix string, text string, suffix string) string {
	single := indent + prefix + strconv.Quote(text) + suffix
	if len(single) <= line_limit {
		return single + "\n"
	}
	var wrapped strings.Builder
	wrapped.WriteString(indent + prefix + "(\n")
	chunk := ""
	for _, word := range strings.SplitAfter(text, " ") {
		if chunk != "" && len(indent)+4+len(strconv.Quote(chunk+word)) > line_limit {
			wrapped.WriteString(indent + "    " + strconv.Quote(chunk) + "\n")
			chunk = ""
		}
		chunk += word
	}
	wrapped.WriteString(indent + "    " + strconv.Quote(chunk) + "\n")
	wrapped.WriteString(indent + ")" + suffix + "\n")
	return wrapped.String()
}
